from decimal import Decimal, ROUND_HALF_UP

def solve(args):
    total = sum(item['unit_minor'] * item['quantity'] for item in args['items'])
    discounted = Decimal(total) * (Decimal(10000 - args['discount_bps']) / Decimal(10000))
    return int(discounted.quantize(Decimal('1'), rounding=ROUND_HALF_UP))

